diff --git a/src/scheduler.js b/src/scheduler.js
index 05ca288..b0b8259 100644
--- a/src/scheduler.js
+++ b/src/scheduler.js
@@ -1,2 +1,102 @@
-export function createScheduler() { throw new Error('Not implemented'); }
-export function restoreScheduler() { throw new Error('Not implemented'); }
+const clone = value => value === undefined ? undefined : JSON.parse(JSON.stringify(value));
+const error = code => Object.assign(new Error(code), { code });
+const terminal = status => ['done', 'dead', 'cancelled', 'blocked'].includes(status);
+const unsuccessful = status => ['dead', 'cancelled', 'blocked'].includes(status);
+
+function build(state) {
+  const jobs = state.jobs;
+  const find = id => {
+    const job = jobs.get(id);
+    if (!job) throw error('UNKNOWN_JOB');
+    return job;
+  };
+  const view = job => clone(job);
+  const refresh = () => {
+    // Submission order is topological because dependencies must already exist.
+    for (const job of jobs.values()) {
+      if (terminal(job.status) || job.status === 'leased') continue;
+      const bad = job.dependsOn.find(id => unsuccessful(jobs.get(id).status));
+      if (bad !== undefined) {
+        job.status = 'blocked';
+        job.blockedBy = bad;
+      } else {
+        delete job.blockedBy;
+        job.status = job.dependsOn.every(id => jobs.get(id).status === 'done') ? 'ready' : 'waiting';
+      }
+    }
+  };
+  const clearLease = job => { delete job.worker; delete job.token; delete job.leaseUntil; };
+  const finishFailure = (job, message) => {
+    job.lastError = message;
+    clearLease(job);
+    if (job.attempt < state.maxAttempts) {
+      job.status = 'ready';
+      job.availableAt = state.now + state.retryBase * 2 ** (job.attempt - 1);
+    } else job.status = 'dead';
+    refresh();
+  };
+  const leased = ({id, worker, token}) => {
+    const job = find(id);
+    if (job.status !== 'leased' || job.worker !== worker || job.token !== token) throw error('LEASE_LOST');
+    return job;
+  };
+  return {
+    submit({id, dependsOn = [], priority = 0} = {}) {
+      if (typeof id !== 'string' || !id || !Number.isSafeInteger(priority)) throw error('INVALID_INPUT');
+      if (jobs.has(id)) throw error('JOB_EXISTS');
+      if (!Array.isArray(dependsOn) || dependsOn.some(dep => typeof dep !== 'string' || !dep) || new Set(dependsOn).size !== dependsOn.length || dependsOn.includes(id)) throw error('INVALID_DEPENDENCIES');
+      if (dependsOn.some(dep => !jobs.has(dep))) throw error('UNKNOWN_DEPENDENCY');
+      const job = {id, dependsOn: clone(dependsOn), priority, sequence: state.nextSequence++, status: 'waiting', attempt: 0, availableAt: state.now};
+      jobs.set(id, job); refresh(); return view(job);
+    },
+    get(id) { return view(find(id)); },
+    claim({worker, leaseFor} = {}) {
+      if (typeof worker !== 'string' || !worker || !Number.isSafeInteger(leaseFor) || leaseFor <= 0) throw error('INVALID_INPUT');
+      const job = [...jobs.values()].filter(item => item.status === 'ready' && item.availableAt <= state.now)
+        .sort((a, b) => b.priority - a.priority || a.sequence - b.sequence || (a.id < b.id ? -1 : a.id > b.id ? 1 : 0))[0];
+      if (!job) return null;
+      job.status = 'leased'; job.attempt++; job.worker = worker; job.token = state.nextToken++; job.leaseUntil = state.now + leaseFor;
+      return view(job);
+    },
+    renew(input = {}) {
+      const {leaseFor} = input;
+      if (!Number.isSafeInteger(leaseFor) || leaseFor <= 0) throw error('INVALID_INPUT');
+      const job = leased(input); job.leaseUntil = Math.max(job.leaseUntil, state.now + leaseFor); return view(job);
+    },
+    complete(input = {}) {
+      const job = leased(input);
+      if (input.result !== undefined) job.result = clone(input.result); else delete job.result;
+      delete job.lastError; clearLease(job); job.status = 'done'; refresh(); return view(job);
+    },
+    fail(input = {}) {
+      if (typeof input.error !== 'string' || !input.error) throw error('INVALID_INPUT');
+      const job = leased(input); finishFailure(job, input.error); return view(job);
+    },
+    cancel(id) {
+      const job = find(id); if (terminal(job.status)) throw error('JOB_TERMINAL');
+      clearLease(job); job.status = 'cancelled'; refresh(); return view(job);
+    },
+    advance(time) {
+      if (!Number.isSafeInteger(time) || time < 0 || time < state.now) throw error('INVALID_TIME');
+      state.now = time;
+      const expired = [...jobs.values()].filter(job => job.status === 'leased' && job.leaseUntil <= time)
+        .sort((a, b) => a.leaseUntil - b.leaseUntil || a.sequence - b.sequence);
+      const ids = [];
+      for (const job of expired) { ids.push(job.id); finishFailure(job, 'LEASE_EXPIRED'); }
+      return {now: state.now, expired: ids};
+    },
+    snapshot() { return {schemaVersion: 1, now: state.now, retryBase: state.retryBase, maxAttempts: state.maxAttempts, nextSequence: state.nextSequence, nextToken: state.nextToken, jobs: [...jobs.values()].map(view)}; }
+  };
+}
+
+export function createScheduler({now = 0, retryBase = 2, maxAttempts = 3} = {}) {
+  if (!Number.isSafeInteger(now) || now < 0 || !Number.isSafeInteger(retryBase) || retryBase <= 0 || !Number.isSafeInteger(maxAttempts) || maxAttempts <= 0) throw error('INVALID_INPUT');
+  return build({now, retryBase, maxAttempts, nextSequence: 0, nextToken: 1, jobs: new Map()});
+}
+
+export function restoreScheduler(snapshot) {
+  const state = {now: snapshot.now, retryBase: snapshot.retryBase, maxAttempts: snapshot.maxAttempts,
+    nextSequence: snapshot.nextSequence, nextToken: snapshot.nextToken,
+    jobs: new Map(snapshot.jobs.map(job => [job.id, clone(job)]))};
+  return build(state);
+}
diff --git a/tests/scheduler.acceptance.test.js b/tests/scheduler.acceptance.test.js
new file mode 100644
index 0000000..4d4f7a1
--- /dev/null
+++ b/tests/scheduler.acceptance.test.js
@@ -0,0 +1,266 @@
+import { describe, it, expect } from 'vitest';
+import { createScheduler, restoreScheduler } from '../src/scheduler.js';
+
+async function expectCode(call, expected) {
+  try {
+    await call();
+  } catch (error) {
+    expect(error.code).toBe(expected);
+    return;
+  }
+  throw new Error('Expected failure');
+}
+
+const ownKeys = value => Object.keys(value).sort();
+const jobKeys = ['id', 'dependsOn', 'priority', 'sequence', 'status', 'attempt', 'availableAt'];
+
+describe('PulseGraph public scheduler contract', () => {
+  it('[R-1][C-1] constructor validates logical time and retry options', () => {
+    for (const options of [
+      { now: -1 }, { now: 1.5 }, { now: Number.MAX_SAFE_INTEGER + 1 },
+      { retryBase: 0 }, { retryBase: 1.5 }, { retryBase: Number.MAX_SAFE_INTEGER + 1 },
+      { maxAttempts: 0 }, { maxAttempts: 1.5 }, { maxAttempts: Number.MAX_SAFE_INTEGER + 1 },
+    ]) expect(() => createScheduler(options)).toThrow();
+    const scheduler = createScheduler({ now: 4, retryBase: 2, maxAttempts: 3 });
+    expect(scheduler.snapshot()).toMatchObject({ now: 4, retryBase: 2, maxAttempts: 3 });
+  });
+
+  it('[R-2][C-2] submit rejects invalid scalar and dependency inputs atomically', async () => {
+    const s = createScheduler();
+    const a = await s.submit({ id: 'A' });
+    expect(a.status).toBe('ready');
+    const before = s.snapshot();
+    await expectCode(() => s.submit({ id: '', priority: 0 }), 'INVALID_INPUT');
+    expect(s.snapshot()).toEqual(before);
+    await expectCode(() => s.submit({ id: 'bad-priority', priority: 1.2 }), 'INVALID_INPUT');
+    expect(s.snapshot()).toEqual(before);
+    await expectCode(() => s.submit({ id: 'self', dependsOn: ['self'] }), 'INVALID_DEPENDENCIES');
+    expect(s.snapshot()).toEqual(before);
+    await expectCode(() => s.submit({ id: 'dupe-dep', dependsOn: ['A', 'A'] }), 'INVALID_DEPENDENCIES');
+    expect(s.snapshot()).toEqual(before);
+    await expectCode(() => s.submit({ id: 'missing-dep', dependsOn: ['missing'] }), 'UNKNOWN_DEPENDENCY');
+    expect(s.snapshot()).toEqual(before);
+    const b = await s.submit({ id: 'B', dependsOn: ['A'] });
+    expect(b.status).toBe('waiting');
+    expect(s.snapshot().jobs.map(j => j.id)).toEqual(['A', 'B']);
+  });
+
+  it('[R-3][R-4][C-3] submitted dependent of a done job is ready with initial fields', async () => {
+    const s = createScheduler({ now: 7 });
+    await s.submit({ id: 'A' });
+    const a = await s.claim({ worker: 'w', leaseFor: 3 });
+    expect(a.status).toBe('leased');
+    const done = await s.complete({ id: 'A', worker: 'w', token: a.token, result: { ok: true } });
+    expect(done.status).toBe('done');
+    const b = await s.submit({ id: 'B', dependsOn: ['A'] });
+    expect(b).toMatchObject({ id: 'B', dependsOn: ['A'], status: 'ready', attempt: 0, availableAt: 7 });
+    for (const key of jobKeys) expect(b).toHaveProperty(key);
+    expect(b).not.toHaveProperty('result');
+    expect(b).not.toHaveProperty('lastError');
+    expect(s.snapshot().jobs.find(j => j.id === 'B')).toEqual(b);
+  });
+
+  it('[R-3][C-4] unsuccessful dependencies block transitively using dependency order', async () => {
+    const s = createScheduler();
+    await s.submit({ id: 'A' });
+    await s.submit({ id: 'B' });
+    const c = await s.submit({ id: 'C', dependsOn: ['B', 'A'] });
+    const d = await s.submit({ id: 'D', dependsOn: ['C'] });
+    expect(c.status).toBe('waiting');
+    expect(d.status).toBe('waiting');
+    await s.cancel('A');
+    const blockedC = await s.get('C');
+    const blockedD = await s.get('D');
+    expect(blockedC).toMatchObject({ status: 'blocked', blockedBy: 'A' });
+    expect(blockedD).toMatchObject({ status: 'blocked', blockedBy: 'C' });
+  });
+
+  it('[R-5][C-5] claim orders by priority then submission sequence and returns lease fields', async () => {
+    const s = createScheduler();
+    await s.submit({ id: 'A', priority: 5 });
+    await s.submit({ id: 'B', priority: 1 });
+    await s.submit({ id: 'C', priority: 5 });
+    const first = await s.claim({ worker: 'w', leaseFor: 4 });
+    const second = await s.claim({ worker: 'x', leaseFor: 2 });
+    expect(first).toMatchObject({ id: 'A', status: 'leased', attempt: 1, worker: 'w', leaseUntil: 4 });
+    expect(second).toMatchObject({ id: 'C', status: 'leased', attempt: 1, worker: 'x', leaseUntil: 2 });
+    expect(first.token).toBeGreaterThan(0);
+    expect(second.token).toBeGreaterThan(first.token);
+    const third = await s.claim({ worker: 'z', leaseFor: 1 });
+    expect(third).toMatchObject({ id: 'B', status: 'leased', attempt: 1, worker: 'z', leaseUntil: 1 });
+    expect(third.token).toBeGreaterThan(second.token);
+    expect(await s.claim({ worker: 'last', leaseFor: 1 })).toBeNull();
+  });
+
+  it('[R-6][C-6] lease identity is enforced and renewal preserves token', async () => {
+    const s = createScheduler();
+    await s.submit({ id: 'A' });
+    const lease = await s.claim({ worker: 'w', leaseFor: 3 });
+    await expectCode(() => s.renew({ id: 'A', worker: 'wrong', token: lease.token, leaseFor: 1 }), 'LEASE_LOST');
+    await expectCode(() => s.complete({ id: 'A', worker: 'w', token: lease.token + 100, result: null }), 'LEASE_LOST');
+    await expectCode(() => s.fail({ id: 'A', worker: 'wrong', token: lease.token, error: 'e' }), 'LEASE_LOST');
+    expect(await s.get('A')).toMatchObject({ status: 'leased', token: lease.token, leaseUntil: 3 });
+    const renewed = await s.renew({ id: 'A', worker: 'w', token: lease.token, leaseFor: 5 });
+    expect(renewed).toMatchObject({ token: lease.token, leaseUntil: 5, status: 'leased' });
+  });
+
+  it('[R-7][R-11][C-7] result, completion views, and snapshots are detached', async () => {
+    const s = createScheduler();
+    await s.submit({ id: 'A' });
+    const lease = await s.claim({ worker: 'w', leaseFor: 2 });
+    const result = { nested: { value: 1 } };
+    const returned = await s.complete({ id: 'A', worker: 'w', token: lease.token, result });
+    result.nested.value = 9;
+    returned.result.nested.value = 8;
+    expect(await s.get('A')).toMatchObject({ status: 'done', result: { nested: { value: 1 } } });
+    const snap = await s.snapshot();
+    snap.jobs[0].result.nested.value = 7;
+    snap.jobs[0].status = 'dead';
+    expect(await s.get('A')).toMatchObject({ status: 'done', result: { nested: { value: 1 } } });
+    expect((await s.snapshot()).jobs[0]).toMatchObject({ status: 'done', result: { nested: { value: 1 } } });
+  });
+
+  it('[R-8][C-8] retries use exponential backoff and stop at the attempt limit', async () => {
+    const s = createScheduler({ retryBase: 2, maxAttempts: 3 });
+    await s.submit({ id: 'A' });
+    let lease = await s.claim({ worker: 'w', leaseFor: 1 });
+    let job = await s.fail({ id: 'A', worker: 'w', token: lease.token, error: 'e1' });
+    expect(job).toMatchObject({ status: 'ready', attempt: 1, availableAt: 2, lastError: 'e1' });
+    expect(await s.claim({ worker: 'w', leaseFor: 1 })).toBeNull();
+    expect(await s.advance(2)).toEqual({ now: 2, expired: [] });
+    lease = await s.claim({ worker: 'w', leaseFor: 1 });
+    job = await s.fail({ id: 'A', worker: 'w', token: lease.token, error: 'e2' });
+    expect(job).toMatchObject({ status: 'ready', attempt: 2, availableAt: 6, lastError: 'e2' });
+    expect(await s.advance(6)).toEqual({ now: 6, expired: [] });
+    lease = await s.claim({ worker: 'w', leaseFor: 1 });
+    job = await s.fail({ id: 'A', worker: 'w', token: lease.token, error: 'e3' });
+    expect(job).toMatchObject({ status: 'dead', attempt: 3, lastError: 'e3' });
+    expect(await s.claim({ worker: 'w', leaseFor: 1 })).toBeNull();
+  });
+
+  it('[R-9][C-9] cancellation invalidates active leases and rejects terminal or unknown IDs', async () => {
+    const s = createScheduler();
+    await s.submit({ id: 'A' });
+    await s.submit({ id: 'B' });
+    const lease = await s.claim({ worker: 'w', leaseFor: 5 });
+    expect(lease.id).toBe('A');
+    const bLease = await s.claim({ worker: 'x', leaseFor: 5 });
+    expect(bLease.id).toBe('B');
+    await s.complete({ id: 'B', worker: 'x', token: bLease.token, result: true });
+    const cancelled = await s.cancel('A');
+    expect(cancelled).toMatchObject({ status: 'cancelled' });
+    expect(cancelled).not.toHaveProperty('worker');
+    expect(cancelled).not.toHaveProperty('token');
+    await expectCode(() => s.complete({ id: 'A', worker: 'w', token: lease.token, result: true }), 'LEASE_LOST');
+    await expectCode(() => s.cancel('B'), 'JOB_TERMINAL');
+    await expectCode(() => s.cancel('unknown'), 'UNKNOWN_JOB');
+  });
+
+  it('[R-10][C-10] advance rejects invalid time atomically and expires at inclusive deadlines', async () => {
+    const s = createScheduler();
+    await s.submit({ id: 'A' });
+    await s.submit({ id: 'B' });
+    const a = await s.claim({ worker: 'w', leaseFor: 4 });
+    const b = await s.claim({ worker: 'x', leaseFor: 4 });
+    await s.submit({ id: 'C' });
+    const c = await s.claim({ worker: 'y', leaseFor: 2 });
+    const before = await s.snapshot();
+    for (const time of [-1, 1.2, Number.MAX_SAFE_INTEGER + 1]) {
+      await expectCode(() => s.advance(time), 'INVALID_TIME');
+      expect(await s.snapshot()).toEqual(before);
+    }
+    expect([a.id, b.id, c.id]).toEqual(['A', 'B', 'C']);
+    expect(await s.advance(2)).toEqual({ now: 2, expired: ['C'] });
+    expect(await s.get('C')).toMatchObject({ status: 'ready', lastError: 'LEASE_EXPIRED' });
+    expect(await s.advance(4)).toEqual({ now: 4, expired: ['A', 'B'] });
+    expect(await s.get('A')).toMatchObject({ lastError: 'LEASE_EXPIRED' });
+    expect(await s.get('B')).toMatchObject({ lastError: 'LEASE_EXPIRED' });
+  });
+
+  it('[R-11][C-11] snapshot has the exact public shape and detached job views', async () => {
+    const s = createScheduler({ now: 3, retryBase: 4, maxAttempts: 2 });
+    const a = await s.submit({ id: 'A' });
+    const snap = await s.snapshot();
+    expect(ownKeys(snap)).toEqual(['jobs', 'maxAttempts', 'nextSequence', 'nextToken', 'now', 'retryBase', 'schemaVersion']);
+    expect(ownKeys(snap.jobs[0])).toEqual([...jobKeys].sort());
+    expect(snap.jobs[0]).toEqual(a);
+    snap.now = 99;
+    snap.jobs[0].dependsOn.push('mutated');
+    expect(await s.get('A')).toEqual(a);
+    expect(await s.snapshot()).toMatchObject({ now: 3, jobs: [a] });
+  });
+
+  it('[R-12][C-12] JSON-cloned restore preserves leases, retries, token history, and independence', async () => {
+    const s = createScheduler({ retryBase: 2, maxAttempts: 3 });
+    await s.submit({ id: 'A' });
+    let aLease = await s.claim({ worker: 'w', leaseFor: 5 });
+    await s.fail({ id: 'A', worker: 'w', token: aLease.token, error: 'retry' });
+    await s.submit({ id: 'B' });
+    const bLease = await s.claim({ worker: 'x', leaseFor: 5 });
+    const restored = restoreScheduler(JSON.parse(JSON.stringify(await s.snapshot())));
+    expect(await restored.snapshot()).toEqual(await s.snapshot());
+    expect((await restored.get('B')).token).toBe(bLease.token);
+    expect(await s.advance(2)).toEqual({ now: 2, expired: [] });
+    expect(await restored.advance(2)).toEqual({ now: 2, expired: [] });
+    aLease = await s.claim({ worker: 'w2', leaseFor: 3 });
+    const restoredALease = await restored.claim({ worker: 'w2', leaseFor: 3 });
+    expect(aLease).toEqual(restoredALease);
+    expect(aLease.token).toBeGreaterThan(bLease.token);
+    await s.cancel('B');
+    expect((await s.get('B')).status).toBe('cancelled');
+    expect((await restored.get('B')).status).toBe('leased');
+  });
+
+  it('[R-5][R-13][R-6][C-13] claim does not expire a lease before logical time advances', async () => {
+    const s = createScheduler();
+    await s.submit({ id: 'A' });
+    const lease = await s.claim({ worker: 'w1', leaseFor: 1 });
+    expect(await s.claim({ worker: 'w2', leaseFor: 1 })).toBeNull();
+    expect(await s.get('A')).toMatchObject({ status: 'leased', worker: 'w1', token: lease.token, leaseUntil: 1 });
+    expect(await s.advance(1)).toEqual({ now: 1, expired: ['A'] });
+    await expectCode(() => s.complete({ id: 'A', worker: 'w1', token: lease.token, result: null }), 'LEASE_LOST');
+  });
+
+  it('[R-7][C-14] completing a retry clears its error and readies dependents', async () => {
+    const s = createScheduler();
+    await s.submit({ id: 'A' });
+    const b = await s.submit({ id: 'B', dependsOn: ['A'] });
+    expect(b.status).toBe('waiting');
+    let lease = await s.claim({ worker: 'w', leaseFor: 1 });
+    const failed = await s.fail({ id: 'A', worker: 'w', token: lease.token, error: 'temporary' });
+    expect(failed).toMatchObject({ status: 'ready', lastError: 'temporary' });
+    expect((await s.get('B')).status).toBe('waiting');
+    await s.advance(failed.availableAt);
+    lease = await s.claim({ worker: 'w', leaseFor: 1 });
+    const done = await s.complete({ id: 'A', worker: 'w', token: lease.token, result: { ok: true } });
+    expect(done).toMatchObject({ status: 'done', result: { ok: true } });
+    expect(done).not.toHaveProperty('lastError');
+    expect(done).not.toHaveProperty('leaseUntil');
+    expect((await s.get('B')).status).toBe('ready');
+  });
+
+  it('[R-2][C-15] duplicate job IDs throw JOB_EXISTS and preserve the original', async () => {
+    const s = createScheduler();
+    const original = await s.submit({ id: 'A' });
+    await expectCode(() => s.submit({ id: 'A' }), 'JOB_EXISTS');
+    expect(await s.get('A')).toEqual(original);
+    expect((await s.snapshot()).jobs).toHaveLength(1);
+  });
+
+  it('[R-10][R-8][R-5][C-16] repeated lease expiry orders jobs and applies retry then dead behavior', async () => {
+    const s = createScheduler({ retryBase: 2, maxAttempts: 2 });
+    await s.submit({ id: 'A' });
+    await s.submit({ id: 'B' });
+    expect((await s.claim({ worker: 'w', leaseFor: 3 })).id).toBe('A');
+    expect((await s.claim({ worker: 'x', leaseFor: 3 })).id).toBe('B');
+    expect(await s.advance(3)).toEqual({ now: 3, expired: ['A', 'B'] });
+    for (const id of ['A', 'B']) expect(await s.get(id)).toMatchObject({ status: 'ready', attempt: 1, availableAt: 5, lastError: 'LEASE_EXPIRED' });
+    expect(await s.advance(5)).toEqual({ now: 5, expired: [] });
+    const a2 = await s.claim({ worker: 'w', leaseFor: 1 });
+    const b2 = await s.claim({ worker: 'x', leaseFor: 1 });
+    expect(a2).toMatchObject({ id: 'A', attempt: 2, leaseUntil: 6 });
+    expect(b2).toMatchObject({ id: 'B', attempt: 2, leaseUntil: 6 });
+    expect(await s.advance(6)).toEqual({ now: 6, expired: ['A', 'B'] });
+    for (const id of ['A', 'B']) expect(await s.get(id)).toMatchObject({ status: 'dead', attempt: 2, lastError: 'LEASE_EXPIRED' });
+  });
+});
